import math

def plan_locations(total_users, weights, users_per_engine):
    total_w = sum(weights.values())
    plan = {}
    for loc, w in weights.items():
        users = round(total_users * w / total_w)
        plan[loc] = {"users": users, "engines": math.ceil(users / users_per_engine) if users else 0}
    return plan

